L23_1 = "\227\130\183\227\131\139\227\130\162\227\129\171\227\129\175\227\129\132\227\129\164\228\188\154\227\129\136\227\130\139\227\129\139\227\130\143\227\129\139\227\130\137\227\129\170\227\129\132\227\129\151\227\128\129\231\181\166\230\150\153\227\130\146\227\129\130\227\129\146\227\130\139\231\164\190\229\147\161\227\129\175\229\162\151\227\129\136\227\129\161\227\130\131\227\129\163\227\129\159\227\129\151\227\128\130"
